#![allow(unused)]
use verus::prelude::*;

verus! {

/// Insert `delimiter` between every pair of consecutive elements of `numbers`.
/// If `numbers.len() <= 1`, returns `numbers` unchanged.
/// Otherwise returns a vector of length `2*n - 1` (where `n = numbers.len()`),
/// such that
///   - for all `k < n`, `result[2*k] == numbers[k]`,
///   - for all `d < n-1`, `result[2*d + 1] == delimiter`.
pub fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8>
    ensures
        if numbers.len() <= 1 {
            // unchanged
            result == numbers
        } else {
            let n = numbers.len();
            result.len() == 2 * n - 1
            && forall(|k: usize| k < n ==> result[2*k] == numbers[k])
            && forall(|d: usize| d < n - 1 ==> result[2*d + 1] == delimiter)
        }
{
    let n = numbers.len();
    // For length 0 or 1, nothing to do.
    if n <= 1 {
        return numbers.clone();
    }

    // Pre-allocate the needed capacity: 2*n - 1
    let mut res = Vec::with_capacity(2 * n - 1);

    // Push the first element
    res.push(numbers[0]);

    // We will iterate i = 1..n, each time inserting a delimiter then numbers[i]
    let mut i: usize = 1;
    while i < n
        invariant i <= n
        invariant res.len() == 2 * i - 1
        // All even indices up to 2*(i-1) are the original numbers
        invariant forall(|k: usize| k < i ==> res[2*k] == numbers[k])
        // All odd indices up to 2*(i-1)-1 are delimiters
        invariant forall(|d: usize| d < i - 1 ==> res[2*d + 1] == delimiter)
        decreases n - i
    {
        res.push(delimiter);
        res.push(numbers[i]);
        i += 1;
    }

    // At this point i == n, so res.len() == 2*n - 1 and the invariants
    // establish the final specification.
    res
}

} // verus!